foreach ($key in $logos.Keys) {
  $url = $logos[$key]
  $out = Join-Path (Get-Location) $key
  try {
    Invoke-WebRequest -Uri $url -OutFile $out -UserAgent "Mozilla/5.0"
    Write-Output "Downloaded: $key"
  } catch {
    Write-Output "Error on $key"
  }
}
